// THE SCORE: timings come from the Mandarin dialogue (vo.js, generated by narration.py),
// so lip-sync, captions, the light-ray gag, footsteps and sounds all share one clock.
(function () {
  const node = typeof require !== 'undefined';
  const U = node ? require('./engine/util') : globalThis.U;
  const MU = node ? require('./engine/music') : globalThis.MUSIC;
  const VO = node ? require('./vo') : globalThis.VO;
  const { m, makeClock, makeChords } = MU;

  const FPS = 30;
  const FORMAT = U.pickFormat('16:9');
  const [W, H] = U.formatSize(FORMAT);
  const SAFE = U.safeArea(W, H);
  const WIDE = W / H > 1.2;
  const clock = makeClock({ bpm: 120, offset: 0 });
  const { T, BEAT } = clock;
  const L = VO.lines;
  const ph = (i, k) => L[i].phrases[k][1];

  const ev = {
    hello: L[0].t,
    ask: L[1].t,
    why: ph(1, 2),
    answer: L[2].t,
    red: ph(2, 2), // "紅色的光被吸收了"
    blue: ph(2, 3), // "藍色的光回到我們的眼睛裡"
    go: L[3].t,
    follow: ph(3, 2), // "跟著我的腳印走"
  };
  ev.redGone = ev.red + 1.3; // the red ray dies in the ice
  ev.blueEye = ev.blue + 1.1; // the blue ray reaches the tourist's eye: ding
  ev.walk = ev.follow + 0.3;
  const DURATION = Math.ceil(L[3].end + 6.0);
  ev.title = DURATION - 3.4;

  // walkers: a line of hikers following the guide toward the far left of the glacier
  const STEP = 0.42; // seconds per footstep (2 per walk cycle)
  const walkers = [
    { id: 'guide', x0: 560, delay: 0.0 },
    { id: 'asker', x0: 1130, delay: 0.55 },
    { id: 'friend', x0: 1330, delay: 0.95 },
    { id: 'kid', x0: 1500, delay: 1.3 },
  ];
  const steps = [];
  for (const w of walkers) for (let t = ev.walk + w.delay; t < DURATION - 1.2; t += STEP) steps.push({ t: +t.toFixed(3), who: w.id });

  const S = {
    hello: [0, ev.ask],
    question: [ev.ask, ev.answer],
    answer: [ev.answer, ev.go],
    walk: [ev.go, DURATION],
  };

  const { chords } = makeChords(clock, {
    Fmaj7: { notes: ['A3', 'C4', 'E4'], bass: 'F2' },
    Am7: { notes: ['G3', 'C4', 'E4'], bass: 'A2' },
    Dm7: { notes: ['A3', 'C4', 'F4'], bass: 'D2' },
    Bbmaj7: { notes: ['A3', 'D4', 'F4'], bass: 'Bb1' },
  }, Array.from({ length: Math.ceil(DURATION / 2 / 4) * 4 }, (_, i) => [i, 0, 4, ['Fmaj7', 'Am7', 'Dm7', 'Bbmaj7'][Math.floor(i / 2) % 4]]));

  const markers = {
    hello: ev.hello, ask: ev.ask, red: ev.redGone, blueEye: { t: ev.blueEye, sync: 'a' },
    go: ev.go, walk: ev.walk, title: ev.title,
  };

  const SCORE = { FPS, FORMAT, W, H, SAFE, WIDE, DURATION, clock, T, BEAT, S, m, chords, ev, markers, VO, STEP, walkers, steps };
  if (node) module.exports = SCORE; else globalThis.SCORE = SCORE;
})();
